const staticData = $getWorkflowStaticData('global');
const content = String($json.data?.content || $('Switch1').item.json.data?.content || '').trim();

const parts = content.split(/\s+/);
const cmd = (parts[0] || '').toUpperCase();
let reply = '';

if (cmd === '#STATUS' || cmd === '#CEK') {
  const st = staticData.lastStatus;
  if (!st) {
    reply = '⚠️ *[STATUS BOT TUNTAS]*\nBelum ada laporan dari laptop/PC.\nPastikan ekstensi TUNTAS aktif di browser.';
  } else {
    reply = `📊 *[STATUS BOT TUNTAS | ${st.pc || 'PC 1'}]*\n` +
      `⚡ Status: *${st.status}*\n` +
      `📈 Kemajuan: *${st.progress}*\n` +
      `🏢 Usaha: ${st.nama_usaha || '-'}\n` +
      `✅ Sukses: ${st.successCount || 0} | ❌ Gagal: ${st.failedCount || 0}\n` +
      `📶 Server FASIH: ${st.serverHealth || 'Normal'}\n` +
      `⏰ Sinkron Terakhir: ${st.updatedAt || '-'}`;
  }
} else if (cmd === '#JEDA' || cmd === '#PAUSE') {
  staticData.pendingCommand = { action: 'PAUSE', by: 'WhatsApp' };
  reply = '⏸️ *[PERINTAH JEDA DITERIMA]*\nPerintah jeda telah dikirim ke bot PC Anda.';
} else if (cmd === '#LANJUT' || cmd === '#RESUME') {
  staticData.pendingCommand = { action: 'RESUME', by: 'WhatsApp' };
  reply = '▶️ *[PERINTAH LANJUT DITERIMA]*\nPerintah lanjut telah dikirim ke bot PC Anda.';
} else if (cmd === '#STOP' || cmd === '#BERHENTI') {
  staticData.pendingCommand = { action: 'STOP', by: 'WhatsApp' };
  reply = '⏹️ *[PERINTAH STOP DITERIMA]*\nPerintah stop telah dikirim ke bot PC Anda.';
} else if (cmd === '#TAMBAH') {
  const link = parts[1] || '';
  if (!link.startsWith('http')) {
    reply = '⚠️ Format link tidak valid.\nContoh format yang benar:\n*#TAMBAH https://fasih-sm.bps.go.id/...*';
  } else {
    staticData.pendingCommand = { action: 'ADD_QUEUE', link: link.trim() };
    reply = `➕ *[ANTRIAN DITAMBAHKAN]*\nTautan baru berhasil dikirim ke antrian bot:\n${link}`;
  }
} else {
  reply = '🤖 *[PANDUAN PERINTAH BOT TUNTAS]*\n' +
    'Gunakan salah satu perintah berikut:\n\n' +
    '• *#STATUS* : Cek progres antrian & server\n' +
    '• *#JEDA* : Menjeda bot dari jarak jauh\n' +
    '• *#LANJUT* : Melanjutkan bot yang dijeda\n' +
    '• *#STOP* : Menghentikan otomasi bot\n' +
    '• *#TAMBAH [link]* : Tambah link ke antrian';
}

return { json: { replyMessage: reply } };

const staticData = $getWorkflowStaticData('global');
const body = $json.body || {};

if (body.pc || body.status) {
  staticData.lastStatus = {
    pc: body.pc || 'PC 1',
    status: body.status || 'IDLE',
    progress: body.progress || '0 / 0',
    nama_usaha: body.nama_usaha || '-',
    successCount: body.successCount || 0,
    failedCount: body.failedCount || 0,
    serverHealth: body.serverHealth || 'Normal (1.0x)',
    updatedAt: new Date().toLocaleTimeString('id-ID')
  };
}

let commandToSend = { action: 'NONE' };
if (staticData.pendingCommand) {
  commandToSend = staticData.pendingCommand;
  staticData.pendingCommand = null;
}

return { json: { status: 'OK', command: commandToSend } };
